using System.Buffers.Binary;
using RiftReader2.Application;
using RiftReader2.Domain;
namespace RiftReader2.Live.Tests;
public sealed class CurrentBuildPlayerRaceSampleCommandTests
{
 const ulong M=0x140000000,E=0x20000000,H=0x20010000,O=0x20020000,R=0x20030000;
 [Fact] public void CapturesRawKeyAndNullProvider(){var s=Fixture();var r=Read(s);Assert.Equal("raw-candidate",r.ReferentStatus);Assert.Equal(77U,r.RawRaceKey);Assert.Equal("null-provider",r.ProviderStatus);}
 [Fact] public void NullReferentIsUnavailableNotZero(){var s=Fixture();s.Put(H+0x48,Q(0));var r=Read(s);Assert.Equal("null-referent",r.ReferentStatus);Assert.Null(r.RawRaceKey);}
 [Fact] public void ChangedReferentOrSelfFails(){var s=Fixture();s.Change(R+0x30,BitConverter.GetBytes(78U));Assert.Throws<InvalidDataException>(()=>Read(s));s=Fixture();int i=0;Assert.Throws<InvalidDataException>(()=>CurrentBuildPlayerRaceSampleCommand.Read(s,_=>Context(s,++i==1?E:E+8),_=>new(44,E,H,()=>{})));}
 [Fact] public void TypedRaceTextCandidateIsCaptured(){var s=Fixture();SetupRace(s);var r=ReadRace(s);Assert.Equal("type-0718-text-candidate",r.RaceRecordStatus);Assert.Equal("Human",r.RaceTextCandidate);Assert.Equal("raw-candidate",r.ReferentStatus);}
 [Fact] public void TypeMismatchDoesNotExposeText(){var s=Fixture();SetupRace(s);s.Put(0x20080000,Q(M+0x1000));var r=ReadRace(s);Assert.Equal("unverified-type",r.RaceRecordStatus);Assert.Null(r.RaceTextCandidate);}
 [Fact] public void ChangedTextRejects(){var s=Fixture();SetupRace(s);s.Change(0x20090000,new byte[]{(byte)'X'});Assert.Throws<InvalidDataException>(()=>ReadRace(s));}
 [Fact] public void ThreadEpochChangedRejects(){var s=Fixture();SetupRace(s);int n=0;Assert.Throws<InvalidDataException>(()=>CurrentBuildPlayerRaceSampleCommand.Read(s,_=>Context(s,E),_=>new(44,E,H,()=>{}),()=>[new NativeThreadEpoch(77,++n,0x20050000)]));}
 [Fact] public void CapturesLocalizedFallbackAndMode(){var s=Fixture();SetupRace(s);SetupLocalized(s);var r=ReadRace(s);Assert.Equal("raw-candidate",r.LocalizedNameSeed!.Status);Assert.Equal(1,r.LocalizedNameSeed.LocalizationMode);Assert.Equal("Human Name",r.LocalizedNameSeed.FallbackText);}
 [Fact] public void LocalizedChildMutationRejects(){var s=Fixture();SetupRace(s);SetupLocalized(s);s.Change(0x200C0000+0x18,BitConverter.GetBytes(2U));Assert.Throws<InvalidDataException>(()=>ReadRace(s));}
 static void SetupLocalized(Fake s){const ulong Child=0x200C0000,Text=0x200D0000,Manager=0x200E0000;s.Put(M+0x33623E8,Q(Manager));s.Put(Manager+4,BitConverter.GetBytes(1));s.Put(0x20080000+0x280,Q(Child));s.Put(Child,Q(M+0x27F24F8));s.Put(M+0x27F2538,Q(M+0x170C5D0));s.Put(M+0x3417970,Q(M+0x2802E40));s.Put(M+0x2802E48,Q(M+0x17361E0));s.Put(Child+0x18,new byte[4]);s.Put(Child+0x20,Q(Text));var raw=new byte[256];System.Text.Encoding.Unicode.GetBytes("Human Name\0").CopyTo(raw,0);s.Put(Text,raw);}
 static PlayerRaceSeedObservation ReadRace(Fake s)=>CurrentBuildPlayerRaceSampleCommand.Read(s,_=>Context(s,E),_=>new(44,E,H,()=>{}),()=>[new NativeThreadEpoch(77,1,0x20050000)]);
 static void SetupRace(Fake s){const ulong P=0x20040000,T=0x20050000,W=0x20060000,C=0x20070000,Obj=0x20080000,Text=0x20090000,B=0x200A0000,Holder=0x200B0000;s.Put(M+0x336F1F8,Q(P));s.Put(P+0x40,new byte[]{3,0});s.Put(M+0x3372C18,Q(W));s.Put(W,Q(C));s.Put(C+0x274,new byte[4]);var ti=new byte[32];Q(T).CopyTo(ti,0);Q(123).CopyTo(ti,16);Q(77).CopyTo(ti,24);s.Put(T+0x30,ti);s.Put(T+0x1480,Q(0));var h=new byte[32];Q(B).CopyTo(h,0);Q(24).CopyTo(h,8);Q(1).CopyTo(h,16);s.Put(C+0x220,h);var node=new byte[24];node[8]=3;BitConverter.GetBytes(77U).CopyTo(node,12);Q(Holder).CopyTo(node,16);s.Put(B,node);s.Put(Holder+0x18,Q(Obj));s.Put(Obj,Q(M+0x2C68CA0));s.Put(M+0x2C68CE0,Q(M+0x2173B90));s.Put(M+0x3576360,Q(M+0x2C6B2C0));s.Put(M+0x2C6B2C8,Q(M+0x2196D70));s.Put(Obj+0x118,Q(Text));var bytes=System.Text.Encoding.UTF8.GetBytes("Human\0");for(int i=0;i<bytes.Length;i++)s.Put(Text+(ulong)i,[bytes[i]]);}
 static PlayerRaceSeedObservation Read(Fake s)=>CurrentBuildPlayerRaceSampleCommand.Read(s,_=>Context(s,E),_=>new(44,E,H,()=>{}));
 static CurrentBuildPlayerContextObservation Context(Fake s,ulong e)=>new(s.Identity,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,44,e,H,O,H,0,"x",null,null,0,"x",0,"x",false);
 static Fake Fixture(){var s=new Fake();s.Put(H+0x10,Q(E));s.Put(H+0x40,Q(O));s.Put(H+0x48,Q(R));s.Put(R,Q(M+0x1000));s.Put(M+0x1040,Q(M+0x2000));s.Put(R+0x30,BitConverter.GetBytes(77U));s.Put(M+0x336F1F8,Q(0));return s;}
 static byte[] Q(ulong v){var b=new byte[8];BinaryPrimitives.WriteUInt64LittleEndian(b,v);return b;}
 sealed class Fake:IReadOnlyNativeMemorySession{readonly Dictionary<ulong,byte[]> data=[];readonly Dictionary<ulong,byte[]> changed=[];readonly HashSet<ulong> seen=[];public NativeProcessIdentity Identity{get;}=new(123,456,@"C:\RIFT\rift_x64.exe",CurrentBuildPlayerLookup.GameSha256,M,0x4000000);public void Put(ulong a,byte[] b)=>data[a]=b;public void Change(ulong a,byte[] b)=>changed[a]=b;public NativeReadResult Read(ulong a,int n){var b=!seen.Add(a)&&changed.TryGetValue(a,out var c)?c:data.GetValueOrDefault(a);return b is not null&&b.Length>=n?new("success",b[..n],null,null):new("unavailable",[],null,null);}public ValueTask<string?> RevalidateAsync(CancellationToken c)=>ValueTask.FromResult<string?>(null);public ValueTask DisposeAsync()=>ValueTask.CompletedTask;}
}
